const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,text,disabled=false,extra='',primary=false)=>`<button class="btn ${primary?'primary':''}" data-action="${action}" ${disabled?'disabled':''} ${extra}>${text}</button>`;
const phase={charge:'マナ',main:'召喚・呪文',attack:'攻撃'};
export function onlineScreenHTML(state,{user,decks=[],selectedDeckId,code='',selected=null,page=0,art,actionsOpen=false,valid=()=>true,history=[]}={}){
 const room=state.room,game=room?.game,busy=state.busy,disabled=busy||!state.connected;
 const notice=state.error?`<div class="notice" role="alert">${esc(state.error)} ${button('online-refresh','再接続',busy)}</div>`:'';
 if(!user)return `<div class="page-head"><div><div class="eyebrow">PLAY WITH FRIENDS</div><h1>友達と対戦</h1><p>同じルームに参加して、手札を選んで対戦しよう。</p></div></div><section class="panel online-lobby"><h2>Googleでログインしよう</h2><p>それぞれ別のGoogleアカウントで参加します。</p>${button('nav','アカウントを開く',false,'data-view="account"',true)}</section>`;
 if(room&&room.phase==='waiting'&&room.seat===0)return `<div class="page-head"><div><div class="eyebrow">PRIVATE ROOM</div><h1>友達を待っています</h1><p>相手がデッキを選んで参加すると対戦が始まります。</p></div></div>${notice}<section class="panel online-lobby"><small>ルームコード</small><div class="online-room-code">${esc(room.code.slice(0,8))} ${esc(room.code.slice(8))}</div><div class="row">${button('online-copy-code','コードをコピー')}${button('online-copy-link','招待リンクをコピー')}</div><p>相手もGoogleでログインし、このコードまたは招待リンクから参加してください。</p><p class="small">待機ルームの有効期限は作成から6時間です。手札と山札の中身は相手に表示されません。</p>${button('online-cancel','ルームを閉じる',disabled)}${button('online-refresh',busy?'確認中…':'再接続',busy)}</section>`;
 if(game){
 const seat=room.seat,own=game.players[seat],opp=game.players[1-seat],finished=['finished','expired'].includes(room.phase),mine=game.actor===seat&&!finished,all=game.actions||[],cards=[...own.hand,...own.battle,...own.mana,...own.grave,...opp.battle,...opp.mana,...opp.grave],card=cards.find(x=>x.uid===selected),actions=card?all.filter(a=>a.uid===selected):all,pages=Math.max(1,Math.ceil(actions.length/8)),current=Math.max(0,Math.min(page,pages-1));
 const status=finished?room.phase==='expired'?'ルームの有効期限が切れました':game.draw?'引き分け':game.winner===seat?'あなたの勝利！':'相手の勝利':!state.connected?'再接続してください':busy?'送信・更新中…':mine?'あなたの操作':'相手の操作を待っています';
 const title=finished?'対戦終了':game.decision||({charge:'マナに置くカードを選ぼう',main:'召喚・呪文を使おう',attack:'攻撃するクリーチャーを選ぼう'})[game.phase]||'操作を選ぶ';
 const board=(p,who)=>{
  const mine=who===seat;
  const shields=`<div class="play-shields"><span class="zone-caption">◇ <b>${p.shieldCount}</b></span><div class="shield-tiles" data-fit-grid="shields" data-fit-count="${p.shieldCount}" style="--fit-cols:${Math.max(1,Math.min(5,p.shieldCount))};--fit-rows:${Math.max(1,Math.ceil(p.shieldCount/5))}">${Array.from({length:p.shieldCount},(_,i)=>`<span class="shield-tile" aria-label="${mine?'自分':'相手'}のシールド${i+1}">${i+1}</span>`).join('')||'<span class="no-shields">シールドなし</span>'}</div>${p.faceUpShields?.length?button('online-zone','表向き',false,`data-player="${who}" data-zone="faceUpShields"`):''}</div>`;
  const field=`<div class="play-creatures online-field" data-fit-grid="creatures" data-fit-count="${p.battle.length}" style="--fit-cols:${Math.max(1,Math.min(5,p.battle.length))};--fit-rows:${Math.max(1,Math.ceil(p.battle.length/5))}" aria-label="${mine?'自分':'相手'}のバトルゾーン">${p.battle.map((c,i)=>`<article class="play-creature ${c.tapped?'is-tapped':''} ${selected===c.uid?'is-selected':''} ${all.some(a=>a.uid===c.uid)?'is-ready':''}"><button class="creature-tap" data-action="online-card" data-uid="${esc(c.uid)}" aria-label="${esc(c.hidden?'裏向きのカード':c.name)}を選ぶ" aria-pressed="${selected===c.uid}">${!c.hidden&&art?art(c.id):''}<span class="compact-creature-index">${i+1}</span><span class="compact-creature-name">${esc(c.hidden?'裏向き':c.name)}</span><span class="compact-creature-state">${c.tapped?'タップ中':all.some(a=>a.uid===c.uid&&a.kind==='attack')?'攻撃可':''}</span><span class="creature-current-power">${c.hidden?'?':c.type==='gear'?'クロスギア':c.type==='seed'?'タマシード':esc(c.power||0)}</span></button></article>`).join('')||'<div class="play-empty">クリーチャーはまだいません</div>'}</div>`;
  return `<section class="online-player ${mine?'own-field':'opponent-field'}"><div class="play-player"><span class="player-avatar ${mine?'mine':''}">${mine?'YOU':'VS'}</span><strong>${esc(p.name)}</strong><small>${who===game.first?'先攻':'後攻'}</small><button class="field-overview-button" data-action="online-field" data-player="${who}" aria-label="${mine?'自分':'相手'}の場を拡大して見る">場 ${p.battle.length} ↗</button></div><div class="play-resources"><span><b>${p.deckCount}</b> 山札</span><span><b>${p.handCount}</b> 手札${mine?'':'・非公開'}</span><button data-action="online-zone" data-player="${who}" data-zone="mana"><b>${p.mana.length}</b> マナ ›</button><button data-action="online-zone" data-player="${who}" data-zone="grave"><b>${p.grave.length}</b> 墓地 ›</button></div>${mine?field+shields:shields+field}</section>`;
 };
 const hand=own.hand.map(c=>`<button class="hand-shelf-card ${all.some(a=>a.uid===c.uid)?'can-use':''} ${selected===c.uid?'is-selected':''}" data-action="online-card" data-uid="${esc(c.uid)}" aria-pressed="${selected===c.uid}" aria-label="${esc(c.name)}を拡大"><span class="hand-shelf-art">${art?art(c.id):''}</span><span class="hand-shelf-cost">${esc(c.cost)}</span>${all.some(a=>a.uid===c.uid)?`<span class="hand-shelf-ready">${game.phase==='charge'?'マナ':'操作可'}</span>`:''}<strong>${esc(c.name)}</strong></button>`).join('');
 return `<div class="online-match"><header class="online-match-head"><div class="manual-heading"><span class="live-duel-dot"></span><strong>友達と対戦</strong><span class="manual-turn">TURN ${game.turn}</span></div><div>${button('online-refresh','再接続',busy)}${button('online-menu','メニュー')}</div></header>${notice}<div class="manual-turnbar online-turnbar ${mine?'':'is-opponent'}"><strong class="online-connection" role="status">${esc(status)}</strong><ol class="manual-phase">${Object.entries(phase).map(([key,label],i)=>`<li class="${game.phase===key?'is-current':''}" ${game.phase===key?'aria-current="step"':''}><b>${i+1}</b>${label}</li>`).join('')}</ol></div><div class="online-stage"><div class="online-board play-board" role="region" aria-label="対戦の盤面全体">${board(opp,1-seat)}<div class="board-divider"><span>DUEL MASTERS</span><b>VS</b><span>DECK LAB</span></div>${board(own,seat)}</div><section class="online-hand hand-shelf" aria-label="自分の手札"><div class="hand-shelf-head"><strong>手札 <b>${own.handCount}</b></strong><small>左右にスワイプ・タップで拡大</small>${own.deckTop?button('card-detail','山札の上：'+esc(own.deckTop.name),false,`data-id="${esc(own.deckTop.id)}"`):''}<button data-action="online-hand-list">一覧を開く</button></div><div class="online-hand-track hand-shelf-cards">${hand||'<p class="hand-shelf-empty">手札がありません</p>'}</div></section><div class="online-dock"><p>${esc(finished?game.reason:mine?title:status)}</p><div>${button('online-hand-list',`手札一覧 ${own.handCount}`)}${button('online-actions-toggle',actionsOpen?'盤面に戻る':finished?'対戦結果':game.decision?'効果を選ぶ':'操作する',!mine&&!finished,'aria-expanded="'+actionsOpen+'" aria-controls="online-controls"',mine)}${button('online-menu','メニュー')}</div></div>${actionsOpen?`<section class="online-controls" id="online-controls" role="region" aria-label="対戦の操作"><div class="online-controls-head"><h2>${esc(card?card.hidden?'裏向きのカード':card.name:title)}</h2>${button('online-actions-close','盤面に戻る',false,'aria-label="操作パネルを閉じて盤面に戻る"')}</div><div class="online-action-drawer">${card?`<div class="online-card-detail">${!card.hidden&&art?art(card.id):''}<div><strong>${esc(card.hidden?'裏向きのカード':card.name)}</strong><p>コスト ${esc(card.cost??'?')}${card.tapped?' · タップ中':''}${card.under?.length?' · 下に '+card.under.length+'枚':''}</p>${!card.hidden?button('card-detail','能力を見る',false,`data-id="${esc(card.id)}"`):''}</div></div>`:''}${game.numberChoice?'<label class="online-number">宣言する数字 <input class="field" id="online-number" inputmode="numeric" value="0" aria-label="宣言する数字"><small>無限を宣言する場合は「∞」</small></label>':''}<div class="online-actions">${actions.slice(current*8,current*8+8).map(a=>button('online-move',esc(a.label),disabled||!mine,`data-index="${a.id}"`,true)).join('')}</div>${!actions.length&&!finished?`<p class="small">${mine?card?'このカードで選べる操作はありません。':'選べる操作はありません。':esc(status)}</p>`:''}${pages>1?`<div class="online-paging">${button('online-page','前へ',current===0,`data-page="${current-1}"`)}<span>${current+1} / ${pages}</span>${button('online-page','次へ',current===pages-1,`data-page="${current+1}"`)}</div>`:''}${card?button('online-all-actions',game.decision?'効果の選択に戻る':'全操作を表示'):''}${finished?`<p>${esc(status)} · ${esc(game.reason)}</p>${button('online-back','ルーム画面へ')}`:''}</div></section>`:''}</div></div>`;
 }

 const choices=decks.map(d=>`<option value="${esc(d.id)}" ${d.id===selectedDeckId?'selected':''} ${!valid(d)?'disabled':''}>${esc(d.name)}${!valid(d)?'（対戦未対応）':''}</option>`).join(''),hasDeck=decks.some(valid);
 return `<div class="page-head"><div><div class="eyebrow">PLAY WITH FRIENDS</div><h1>友達と対戦</h1><p>ルームコードを共有して、アカウント同士で対戦。</p></div>${button('nav','AI対戦へ',false,'data-view="battle"')}</div>${notice}<div class="online-lobby-grid"><section class="panel online-lobby"><span class="badge green">${esc(user.name)} でログイン中</span><h2>使うデッキ</h2><label>マイデッキから選ぶ<select class="field" id="online-deck" aria-label="オンライン対戦に使うデッキ">${choices||'<option>デッキがありません</option>'}</select></label>${!hasDeck?`<p>40枚すべての効果に対応したデッキが必要です。</p>${button('nav','マイデッキへ',false,'data-view="decks"')}`:''}<p class="small">選んだ構成で対戦します。対戦中に元のデッキを編集しても、盤面には影響しません。</p>${button('online-create',busy?'確認中…':'ルームを作る',busy||!hasDeck,'',true)}</section><section class="panel online-lobby"><h2>友達のルームに参加</h2><label>ルームコード<input class="field" id="online-code" value="${esc(code)}" autocomplete="off" autocapitalize="characters" maxlength="40" placeholder="コピーしたコードを貼り付け" aria-label="ルームコード"></label>${button('online-join','このデッキで参加',busy||!hasDeck,'',true)}${button('online-resume','進行中の対戦を再開',busy)}<p class="small">招待リンクからも参加できます。参加には、それぞれ別のGoogleアカウントが必要です。</p></section></div>${room&&['expired','cancelled','finished'].includes(room.phase)?'<p class="notice">前のルームは終了しています。新しく作成できます。</p>':''}${history.length?`<section class="panel online-lobby"><h2>最近の対戦</h2>${history.slice(0,10).map(h=>`<p>${esc(h.result)} · ${esc(h.opponent)} · ${h.turn}ターン</p>`).join('')}</section>`:''}`;
}
